// Part 14 lesson 3 exercise: an int8 dot-product unit with requantisation and saturation (the core of one output of a quantised layer).
//
// N pairs of signed 8-bit numbers a[i] (activations) and w[i] (weights), packed a[i*8 +: 8], w[i*8 +: 8]. With in_valid high, the result is produced
// after two clocks: one clock to register the dot-product accumulator, followed by one clock for requantisation and output registration.
//   acc = sum(a[i] * w[i]) + bias
//   r   = (acc * mult + 2^(shift-1)) >>> shift
//   y   = clamp(r, lo, 127)   with lo = 0 when relu = 1 and -128 when relu = 0
// Outputs: y (signed 8 bit) and acc (the signed 32-bit accumulator including the bias).
module dot_requant #(
    parameter int N = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [N*8-1:0]        a,
    input  logic [N*8-1:0]        w,
    input  logic signed [31:0]    bias,
    input  logic [15:0]           mult,
    input  logic [4:0]            shift,
    input  logic                  relu,
    output logic                  out_valid,
    output logic signed [7:0]     y,
    output logic signed [31:0]    acc
);
    localparam int LEVELS = (N > 1) ? $clog2(N) : 1;

    logic signed [7:0]  a_op [0:N-1];
    logic signed [7:0]  w_op [0:N-1];
    logic signed [15:0] product_q [0:N-1];
    logic signed [31:0] sum_pipe [0:LEVELS][0:N-1];
    logic signed [31:0] bias_q;

    logic [15:0]        mult_pipe [0:LEVELS];
    logic [4:0]         shift_pipe [0:LEVELS];
    logic               relu_pipe [0:LEVELS];
    logic               valid_pipe [0:LEVELS];

    logic signed [31:0] s_q;
    logic signed [63:0] p, r;
    logic signed [63:0] rnd;

    assign s_q = sum_pipe[LEVELS][0];

    always_comb begin
        p = s_q * $signed({1'b0, mult_pipe[LEVELS]});
        rnd = 64'sd1 <<< (shift_pipe[LEVELS] - 5'd1);
        r = (p + rnd) >>> shift_pipe[LEVELS];
    end

    always_ff @(posedge clk) begin
        if (in_valid) begin
            for (int i = 0; i < N; i++) begin
                a_op[i] <= $signed(a[i*8 +: 8]);
                w_op[i] <= $signed(w[i*8 +: 8]);
            end
            bias_q <= bias;
        end
        mult_pipe[0] <= mult;
        shift_pipe[0] <= shift;
        relu_pipe[0] <= relu;
    end

    always_ff @(posedge clk) begin
        for (int i = 0; i < N; i++)
            product_q[i] <= a_op[i] * w_op[i];
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            valid_pipe[0] <= 1'b0;
            for (int i = 1; i <= LEVELS; i++)
                valid_pipe[i] <= 1'b0;
            out_valid <= 1'b0;
        end else begin
            valid_pipe[0] <= in_valid;
            for (int i = 1; i <= LEVELS; i++)
                valid_pipe[i] <= valid_pipe[i-1];

            for (int i = 1; i <= LEVELS; i++) begin
                mult_pipe[i] <= mult_pipe[i-1];
                shift_pipe[i] <= shift_pipe[i-1];
                relu_pipe[i] <= relu_pipe[i-1];
            end

            out_valid <= valid_pipe[LEVELS];
            if (valid_pipe[LEVELS]) begin
                acc <= s_q;
                if (r > 64'sd127) y <= 8'sd127;
                else if (r < (relu_pipe[LEVELS] ? 64'sd0 : -64'sd128))
                    y <= relu_pipe[LEVELS] ? 8'sd0 : -8'sd128;
                else y <= r[7:0];
            end
        end
    end

    generate
        for (genvar level = 1; level <= LEVELS; level++) begin : g_sum_level
            localparam int SRC_COUNT = (N + (1 << (level-1)) - 1) >> (level-1);
            localparam int DST_COUNT = (SRC_COUNT + 1) / 2;

            for (genvar j = 0; j < DST_COUNT; j++) begin : g_sum_node
                if (level == 1) begin : g_from_products
                    if ((2*j + 1) < N) begin : g_pair
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    $signed(product_q[2*j]) +
                                    $signed(product_q[2*j+1]) + bias_q;
                            else
                                sum_pipe[level][j] <=
                                    $signed(product_q[2*j]) +
                                    $signed(product_q[2*j+1]);
                        end
                    end else begin : g_single
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <= $signed(product_q[2*j]) + bias_q;
                            else
                                sum_pipe[level][j] <= $signed(product_q[2*j]);
                        end
                    end
                end else begin : g_from_sums
                    if ((2*j + 1) < SRC_COUNT) begin : g_pair
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    sum_pipe[level-1][2*j] +
                                    sum_pipe[level-1][2*j+1] + bias_q;
                            else
                                sum_pipe[level][j] <=
                                    sum_pipe[level-1][2*j] +
                                    sum_pipe[level-1][2*j+1];
                        end
                    end else begin : g_single
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <= sum_pipe[level-1][2*j] + bias_q;
                            else
                                sum_pipe[level][j] <= sum_pipe[level-1][2*j];
                        end
                    end
                end
            end
        end
    endgenerate
endmodule
