// Part 14 lesson 3 exercise: an int8 dot-product unit with requantisation and saturation.
module dot_requant #(
    parameter int N = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [N*8-1:0]        a,
    input  logic [N*8-1:0]        w,
    input  logic signed [31:0]    bias,
    input  logic [15:0]           mult,
    input  logic [4:0]            shift,
    input  logic                  relu,
    output logic                  out_valid,
    output logic signed [7:0]     y,
    output logic signed [31:0]    acc
);
    localparam int LEVELS = (N > 1) ? $clog2(N) : 1;

    logic signed [7:0]  a_op [0:N-1];
    logic signed [7:0]  w_op [0:N-1];
    logic signed [15:0] product_q [0:N-1];
    logic signed [31:0] sum_pipe [0:LEVELS][0:N-1];
    logic signed [31:0] bias_pipe [0:LEVELS];

    logic [15:0] mult_pipe [0:LEVELS+1];
    logic [4:0]  shift_pipe [0:LEVELS+1];
    logic        relu_pipe [0:LEVELS+1];
    logic        valid_pipe [0:LEVELS+1];

    logic signed [31:0] s_q;

    // Split the signed 32-bit accumulator into signed 24-bit and 8-bit
    // pieces. Each multiplier therefore fits a signed DSP48E1 operand pair.
    logic signed [23:0] op_lo;
    logic signed [7:0]  op_hi;
    logic signed [16:0] op_mult;
    logic signed [40:0] product_lo_q;
    logic signed [24:0] product_hi_q;
    logic signed [48:0] product_sum_q;
    logic signed [31:0] op_acc_q, product_acc_q, sum_acc_q;

    logic [4:0] op_shift_q, product_shift_q, sum_shift_q;
    logic       op_relu_q, product_relu_q, sum_relu_q;
    logic       op_valid_q, product_valid_q, sum_valid_q;

    logic signed [48:0] product_lo_ext;
    logic signed [48:0] product_hi_ext;
    logic signed [63:0] p, rnd, r;

    assign s_q = sum_pipe[LEVELS][0];

    always_comb begin
        product_lo_ext = {{8{product_lo_q[40]}}, product_lo_q};
        product_hi_ext = {{24{product_hi_q[24]}}, product_hi_q};
        p = {{15{product_sum_q[48]}}, product_sum_q};
        rnd = 64'sd0;
        if (sum_shift_q != 5'd0)
            rnd = 64'sd1 <<< (sum_shift_q - 5'd1);
        r = (p + rnd) >>> sum_shift_q;
    end

    always_ff @(posedge clk) begin
        for (int i = 0; i < N; i++) begin
            if (in_valid) begin
                a_op[i] <= $signed(a[i*8 +: 8]);
                w_op[i] <= $signed(w[i*8 +: 8]);
            end
            product_q[i] <= a_op[i] * w_op[i];
        end

        bias_pipe[0] <= bias;
        for (int i = 1; i <= LEVELS; i++)
            bias_pipe[i] <= bias_pipe[i-1];

        mult_pipe[0] <= mult;
        shift_pipe[0] <= shift;
        relu_pipe[0] <= relu;
        for (int i = 1; i <= LEVELS+1; i++) begin
            mult_pipe[i] <= mult_pipe[i-1];
            shift_pipe[i] <= shift_pipe[i-1];
            relu_pipe[i] <= relu_pipe[i-1];
        end
    end

    always_ff @(posedge clk) begin
        if (in_valid)
            valid_pipe[0] <= 1'b1;
        else
            valid_pipe[0] <= 1'b0;

        for (int i = 1; i <= LEVELS+1; i++)
            valid_pipe[i] <= valid_pipe[i-1];
    end

    // Operand registers, DSP multiplier output registers, then a registered
    // adder reconstructing the full-precision 32x16-bit product.
    always_ff @(posedge clk) begin
        op_lo    <= $signed(s_q[23:0]);
        op_hi    <= $signed(s_q[31:24]);
        op_mult  <= $signed({1'b0, mult_pipe[LEVELS+1]});
        op_acc_q <= s_q;
        op_shift_q <= shift_pipe[LEVELS+1];
        op_relu_q  <= relu_pipe[LEVELS+1];
        op_valid_q <= valid_pipe[LEVELS+1];

        product_lo_q <= op_lo * op_mult;
        product_hi_q <= op_hi * op_mult;
        product_acc_q <= op_acc_q;
        product_shift_q <= op_shift_q;
        product_relu_q <= op_relu_q;
        product_valid_q <= op_valid_q;

        product_sum_q <= product_lo_ext + (product_hi_ext <<< 24);
        sum_acc_q <= product_acc_q;
        sum_shift_q <= product_shift_q;
        sum_relu_q <= product_relu_q;
        sum_valid_q <= product_valid_q;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 0; i <= LEVELS+1; i++)
                valid_pipe[i] <= 1'b0;
            op_valid_q <= 1'b0;
            product_valid_q <= 1'b0;
            sum_valid_q <= 1'b0;
            out_valid <= 1'b0;
        end else begin
            out_valid <= sum_valid_q;
            if (sum_valid_q) begin
                acc <= sum_acc_q;
                if (r > 64'sd127)
                    y <= 8'sd127;
                else if (r < (sum_relu_q ? 64'sd0 : -64'sd128))
                    y <= sum_relu_q ? 8'sd0 : -8'sd128;
                else
                    y <= r[7:0];
            end
        end
    end

    generate
        for (genvar level = 1; level <= LEVELS; level++) begin : g_sum_level
            localparam int SRC_COUNT = (N + (1 << (level-1)) - 1) >> (level-1);
            localparam int DST_COUNT = (SRC_COUNT + 1) / 2;

            for (genvar j = 0; j < DST_COUNT; j++) begin : g_sum_node
                if (level == 1) begin : g_from_products
                    if ((2*j + 1) < N) begin : g_pair
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    $signed(product_q[2*j]) +
                                    $signed(product_q[2*j+1]) +
                                    bias_pipe[LEVELS];
                            else
                                sum_pipe[level][j] <=
                                    $signed(product_q[2*j]) +
                                    $signed(product_q[2*j+1]);
                        end
                    end else begin : g_single
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    $signed(product_q[2*j]) + bias_pipe[LEVELS];
                            else
                                sum_pipe[level][j] <= $signed(product_q[2*j]);
                        end
                    end
                end else begin : g_from_sums
                    if ((2*j + 1) < SRC_COUNT) begin : g_pair
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    sum_pipe[level-1][2*j] +
                                    sum_pipe[level-1][2*j+1] +
                                    bias_pipe[LEVELS];
                            else
                                sum_pipe[level][j] <=
                                    sum_pipe[level-1][2*j] +
                                    sum_pipe[level-1][2*j+1];
                        end
                    end else begin : g_single
                        always_ff @(posedge clk) begin
                            if (level == LEVELS)
                                sum_pipe[level][j] <=
                                    sum_pipe[level-1][2*j] + bias_pipe[LEVELS];
                            else
                                sum_pipe[level][j] <= sum_pipe[level-1][2*j];
                        end
                    end
                end
            end
        end
    endgenerate
endmodule
