// Part 14 lesson 3 exercise: an int8 dot-product unit with requantisation and saturation (the core of one output of a quantised layer).
//
// N pairs of signed 8-bit numbers a[i] (activations) and w[i] (weights), packed a[i*8 +: 8], w[i*8 +: 8]. With in_valid high, the result is produced
// after two clocks: one clock to register the dot-product accumulator, followed by one clock for requantisation and output registration.
//   acc = sum(a[i] * w[i]) + bias
//   r   = (acc * mult + 2^(shift-1)) >>> shift
//   y   = clamp(r, lo, 127)   with lo = 0 when relu = 1 and -128 when relu = 0
// Outputs: y (signed 8 bit) and acc (the signed 32-bit accumulator including the bias).
module dot_requant #(
    parameter int N = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [N*8-1:0]        a,
    input  logic [N*8-1:0]        w,
    input  logic signed [31:0]    bias,
    input  logic [15:0]           mult,
    input  logic [4:0]            shift,
    input  logic                  relu,
    output logic                  out_valid,
    output logic signed [7:0]     y,
    output logic signed [31:0]    acc
);
    logic signed [31:0] s;

    // Split the signed 32-bit accumulator into signed pieces that fit in
    // DSP48E1 multiplier inputs. The 16-bit unsigned multiplier is zero
    // extended to a signed 17-bit operand.
    logic signed [24:0] mul_lo_in;
    logic signed [6:0]  mul_hi_in;
    logic signed [16:0] mul_mult_in;
    logic signed [41:0] mul_lo_q;
    logic signed [23:0] mul_hi_q;
    logic signed [63:0] product_q;

    logic signed [31:0] acc_d0, acc_d1, acc_d2;
    logic [4:0]         shift_d0, shift_d1, shift_d2;
    logic               relu_d0, relu_d1, relu_d2;
    logic               valid_d0, valid_d1, valid_d2;

    logic signed [63:0] rnd, r;

    always_comb begin
        s = bias;
        for (int i = 0; i < N; i++)
            s = s + $signed(a[i*8 +: 8]) * $signed(w[i*8 +: 8]);

        rnd = 64'sd1 <<< (shift_d2 - 5'd1);
        r = (product_q + rnd) >>> shift_d2;
    end

    // The first register stage isolates the dot-product logic from the
    // multiplier. The two product registers are the DSP multiplier stage;
    // product_q registers the sum of the two signed partial products.
    always_ff @(posedge clk) begin
        mul_lo_in   <= $signed(s[24:0]);
        mul_hi_in   <= $signed(s[31:25]);
        mul_mult_in <= $signed({1'b0, mult});

        mul_lo_q <= mul_lo_in * mul_mult_in;
        mul_hi_q <= mul_hi_in * mul_mult_in;

        product_q <=
            {{22{mul_lo_q[41]}}, mul_lo_q} +
            ({{40{mul_hi_q[23]}}, mul_hi_q} <<< 25);

        acc_d0   <= s;
        acc_d1   <= acc_d0;
        acc_d2   <= acc_d1;
        shift_d0 <= shift;
        shift_d1 <= shift_d0;
        shift_d2 <= shift_d1;
        relu_d0  <= relu;
        relu_d1  <= relu_d0;
        relu_d2  <= relu_d1;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            valid_d0 <= 1'b0;
            valid_d1 <= 1'b0;
            valid_d2 <= 1'b0;
            out_valid <= 1'b0;
        end else begin
            valid_d0 <= in_valid;
            valid_d1 <= valid_d0;
            valid_d2 <= valid_d1;
            out_valid <= valid_d2;

            if (valid_d2) begin
                acc <= acc_d2;
                if (r > 64'sd127) y <= 8'sd127;
                else if (r < (relu_d2 ? 64'sd0 : -64'sd128))
                    y <= relu_d2 ? 8'sd0 : -8'sd128;
                else y <= r[7:0];
            end
        end
    end
endmodule
