// Part 14 lesson 3 exercise: an int8 dot-product unit with requantisation and saturation.
module dot_requant #(
    parameter int N = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [N*8-1:0]        a,
    input  logic [N*8-1:0]        w,
    input  logic signed [31:0]    bias,
    input  logic [15:0]           mult,
    input  logic [4:0]            shift,
    input  logic                  relu,
    output logic                  out_valid,
    output logic signed [7:0]     y,
    output logic signed [31:0]    acc
);
    logic signed [31:0] s;

    // Split the signed accumulator into two signed 16-bit operands. Each
    // product fits a DSP48E1 multiplier when mult is represented as signed 17-bit.
    logic signed [31:0] acc_q, acc_d1, acc_d2;
    logic signed [16:0] mult_q;
    logic signed [32:0] prod_lo_q, prod_hi_q;
    logic signed [63:0] product_q;
    logic [4:0] shift_q, shift_d1, shift_d2;
    logic relu_q, relu_d1, relu_d2;
    logic valid_q, valid_d1, valid_d2;

    logic signed [63:0] rnd, r;

    always_comb begin
        s = bias;
        for (int i = 0; i < N; i++)
            s = s + $signed(a[i*8 +: 8]) * $signed(w[i*8 +: 8]);

        if (shift_d2 == 0)
            rnd = 64'sd0;
        else
            rnd = 64'sd1 <<< (shift_d2 - 5'd1);
        r = (product_q + rnd) >>> shift_d2;
    end

    // Operand registers, multiplier registers, then the registered sum of
    // the signed partial products. The latter reconstructs the full product:
    // acc = signed(acc[15:0]) + signed(acc[31:16]) * 2^16.
    always_ff @(posedge clk) begin
        acc_q  <= s;
        mult_q <= $signed({1'b0, mult});

        prod_lo_q <= $signed(acc_q[15:0]) * mult_q;
        prod_hi_q <= $signed(acc_q[31:16]) * mult_q;

        product_q <=
            {{31{prod_lo_q[32]}}, prod_lo_q} +
            ({{31{prod_hi_q[32]}}, prod_hi_q} <<< 16);

        acc_d1   <= acc_q;
        acc_d2   <= acc_d1;
        shift_q  <= shift;
        shift_d1 <= shift_q;
        shift_d2 <= shift_d1;
        relu_q   <= relu;
        relu_d1  <= relu_q;
        relu_d2  <= relu_d1;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            valid_q   <= 1'b0;
            valid_d1  <= 1'b0;
            valid_d2  <= 1'b0;
            out_valid <= 1'b0;
        end else begin
            valid_q   <= in_valid;
            valid_d1  <= valid_q;
            valid_d2  <= valid_d1;
            out_valid <= valid_d2;

            if (valid_d2) begin
                acc <= acc_d2;
                if (r > 64'sd127) y <= 8'sd127;
                else if (r < (relu_d2 ? 64'sd0 : -64'sd128))
                    y <= relu_d2 ? 8'sd0 : -8'sd128;
                else y <= r[7:0];
            end
        end
    end
